public protocol MeshNodeProtocol: AnyObject, Sendable {
    
    /**
     * Broadcast an alert to the mesh. Also persists to local SQLite.
     */
    func announceAlert(alert: AlertProfile) async throws 
    
    /**
     * Broadcast a party to the mesh. Also persists to local SQLite
     * so it's included in backfills to peers who were offline.
     */
    func announceParty(party: PartyProfile) async throws 
    
    func announceProfile(profile: PeerProfile) async throws 
    
    func blobStorageBytes() async  -> UInt64
    
    func evictOldBlobs(maxAgeSecs: UInt64) async 
    
    /**
     * Watch the current campus topics and drop ones that rotated out. Runs
     * on connect; call it again about hourly (inboxes rotate daily) and
     * after re-verifying.
     */
    func refreshCampus() async 
    
    func replyWithProfile(profile: PeerProfile, toPeerId: String) async throws 
    
    func retrievePhoto(blobId: String) async throws  -> Data
    
    func sendInvite(toPeerId: String, payload: InvitePayload) async throws 
    
    func sendInviteAccept(toPeerId: String, payload: InviteAcceptPayload) async throws 
    
    func sendInviteDecline(toPeerId: String) async throws 
    
    func sendLike(toPeerId: String, payload: LikePayload) async throws 
    
    func sendLikeBack(toPeerId: String, payload: LikeBackPayload) async throws 
    
    func sendLikeDeclined(toPeerId: String) async throws 
    
    /**
     * Publish on a topic this node watches sealed (a conversation mailbox).
     */
    func sendRaw(topic: String, payload: Data) async throws 
    
    func shutdown() async 
    
    /**
     * Watch a sealed topic (a conversation mailbox) under `key`.
     */
    func subscribeSealed(topic: String, key: Data) async throws 
    
    func unsubscribeSealed(topic: String) async throws 
    
    func uploadPhoto(data: Data) async throws  -> String
    
}
