public enum MeshError: Swift.Error, Equatable, Hashable, Foundation.LocalizedError {

    
    
    case InvalidAddress
    case ConnectionFailed
    case Timeout
    case ConnectionError(msg: String
    )
    case BlobError(msg: String
    )
    case EnrollError(msg: String
    )
    case NotVerified
    case Unknown

    

    

    
    public var errorDescription: String? {
        String(reflecting: self)
    }
    
}

#if compiler(>=6)
extension MeshError: Sendable {}
#endif

#if swift(>=5.8)
@_documentation(visibility: private)
#endif
public struct FfiConverterTypeMeshError: FfiConverterRustBuffer {
    typealias SwiftType = MeshError

    public static func read(from buf: inout (data: Data, offset: Data.Index)) throws -> MeshError {
        let variant: Int32 = try readInt(&buf)
        switch variant {

        

        
        case 1: return .InvalidAddress
        case 2: return .ConnectionFailed
        case 3: return .Timeout
        case 4: return .ConnectionError(
            msg: try FfiConverterString.read(from: &buf)
            )
        case 5: return .BlobError(
            msg: try FfiConverterString.read(from: &buf)
            )
        case 6: return .EnrollError(
            msg: try FfiConverterString.read(from: &buf)
            )
        case 7: return .NotVerified
        case 8: return .Unknown

         default: throw UniffiInternalError.unexpectedEnumCase
        }
    }

    public static func write(_ value: MeshError, into buf: inout [UInt8]) {
        switch value {

        

        
        
        case .InvalidAddress:
            writeInt(&buf, Int32(1))
        
        
        case .ConnectionFailed:
            writeInt(&buf, Int32(2))
        
        
        case .Timeout:
            writeInt(&buf, Int32(3))
        
        
        case let .ConnectionError(msg):
            writeInt(&buf, Int32(4))
            FfiConverterString.write(msg, into: &buf)
            
        
        case let .BlobError(msg):
            writeInt(&buf, Int32(5))
            FfiConverterString.write(msg, into: &buf)
            
        
        case let .EnrollError(msg):
            writeInt(&buf, Int32(6))
            FfiConverterString.write(msg, into: &buf)
            
        
        case .NotVerified:
            writeInt(&buf, Int32(7))
        
        
        case .Unknown:
            writeInt(&buf, Int32(8))
        
        }
    }
}


#if swift(>=5.8)
@_documentation(visibility: private)
#endif
public func FfiConverterTypeMeshError_lift(_ buf: RustBuffer) throws -> MeshError {
