// Note that we don't yet support `indirect` for enums.
// See https://github.com/mozilla/uniffi-rs/issues/396 for further discussion.
/**
 * Tracks the relationship between us and a specific peer.
 * Stored in SQLite under "fratrat/rel/<peer_id>".
 * The state machine enforces the invite/like guard rules:
 * - Can only like/invite a peer in state None
 * - Group chats bypass this check (handled at call site)
 */

public enum RelationshipState: Equatable, Hashable {
    
    /**
     * No relationship yet
     */
    case none
    /**
     * We swiped right — waiting to see if they like us back
     */
    case liked
    /**
     * They liked us — key encrypted to our pubkey, waiting for us to act
     */
    case likedBy(conversationKeyEnc: Data
    )
    /**
     * Mutual like — conversation open
     */
    case matched(conversationId: String
    )
    /**
     * We sent them a direct invite — waiting for response
     */
    case inviteSent(conversationId: String
    )
    /**
     * They invited us — waiting for our response
     */
    case inviteReceived(conversationId: String, fromName: String, conversationKeyEnc: Data
    )
    /**
     * We accepted their invite — conversation open
     */
    case inviteAccepted(conversationId: String
    )
    /**
     * Declined (either direction)
     */
    case declined





}

#if compiler(>=6)
extension RelationshipState: Sendable {}
#endif

#if swift(>=5.8)
@_documentation(visibility: private)
#endif
public struct FfiConverterTypeRelationshipState: FfiConverterRustBuffer {
    typealias SwiftType = RelationshipState

    public static func read(from buf: inout (data: Data, offset: Data.Index)) throws -> RelationshipState {
        let variant: Int32 = try readInt(&buf)
        switch variant {
        
        case 1: return .none
        
        case 2: return .liked
        
        case 3: return .likedBy(conversationKeyEnc: try FfiConverterData.read(from: &buf)
        )
        
        case 4: return .matched(conversationId: try FfiConverterString.read(from: &buf)
        )
        
        case 5: return .inviteSent(conversationId: try FfiConverterString.read(from: &buf)
        )
        
        case 6: return .inviteReceived(conversationId: try FfiConverterString.read(from: &buf), fromName: try FfiConverterString.read(from: &buf), conversationKeyEnc: try FfiConverterData.read(from: &buf)
        )
        
        case 7: return .inviteAccepted(conversationId: try FfiConverterString.read(from: &buf)
        )
        
        case 8: return .declined
        
        default: throw UniffiInternalError.unexpectedEnumCase
        }
    }

    public static func write(_ value: RelationshipState, into buf: inout [UInt8]) {
        switch value {
        
        
        case .none:
            writeInt(&buf, Int32(1))
        
        
        case .liked:
            writeInt(&buf, Int32(2))
        
        
        case let .likedBy(conversationKeyEnc):
            writeInt(&buf, Int32(3))
            FfiConverterData.write(conversationKeyEnc, into: &buf)
            
        
        case let .matched(conversationId):
